function applyBaseStats(sheet, base) {
  if (!base) return;
  const keys = Object.keys(RESOLVED_STAT_DEFAULTS);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const value = Number(base[key]);
    if (Number.isFinite(value)) sheet[key] = value;
